async function imageDecode(blob: Blob): Promise<NdArray<Uint8Array>> {
  const mime = MimeType.fromString(blob.type);

  switch (mime.type) {
    case 'image/x-alpha8': {
      const width = parseInt(mime.params['width']);
      const height = parseInt(mime.params['height']);
